"""Date ranges."""
from datetime import timedelta


def dates_between(start, end, step=1):
    """The dates from `start` to `end`, every `step` days."""
    if not isinstance(step, int) or step < 1:
        raise ValueError("step must be an int of at least 1")

    if start == end:
        return [start]

    if start < end:
        days = (end - start).days
        return [start + timedelta(days=offset) for offset in range(0, days + 1, step)]
    else:
        days = (start - end).days
        return [start - timedelta(days=offset) for offset in range(0, days + 1, step)]


def count_dates(start, end, step=1):
    """How many dates `dates_between` returns."""
    if not isinstance(step, int) or step < 1:
        raise ValueError("step must be an int of at least 1")

    if start == end:
        return 1

    days = abs((end - start).days)
    return days // step + 1
